import json,re
async def s(q,n=5,w=1500,kw=None):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        if x.get('type')!='web_search_result': print(x);continue
        c=x['content']
        print(x['url'],x['title'][:80])
        if kw:
            for k in kw:
                for m in re.finditer(k,c):
                    print("   >",c[max(0,m.start()-100):m.start()+250].replace("\n"," "));break
        else: print(c[:w].replace("\n"," "))
    return r
